import{_ as n,C as r,o,c as i,j as t,a,E as l,a2 as d}from"./chunks/framework.BSl-aDiU.js";const k=JSON.parse('{"title":"4. Levels & balance","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/levels.md","filePath":"gdd/levels.md"}'),h={name:"gdd/levels.md"},p={id:"_4-1-balance-rule-balance-rule",tabindex:"-1"},g={id:"_4-2-level-checker-checker",tabindex:"-1"},m={id:"_4-3-shipped-levels",tabindex:"-1"};function c(u,e,b,v,f,y){const s=r("Badge");return o(),i("div",null,[e[9]||(e[9]=t("h1",{id:"_4-levels-balance",tabindex:"-1"},[a("4. Levels & balance "),t("a",{class:"header-anchor",href:"#_4-levels-balance","aria-label":'Permalink to "4. Levels & balance"'},"​")],-1)),t("h2",p,[e[0]||(e[0]=a("4.1 Balance rule {#balance-rule} ",-1)),l(s,{type:"tip",text:"Live"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#_4-1-balance-rule-balance-rule","aria-label":'Permalink to "4.1 Balance rule {#balance-rule} <Badge type="tip" text="Live" />"'},"​",-1))]),e[10]||(e[10]=d('<blockquote><p>For every colour, the <strong>total ammo of that colour&#39;s fighters</strong> must equal the <strong>total hit points of that colour&#39;s enemies and boss parts</strong> across all stages.</p></blockquote><p>With the default 18 ammo per fighter, each colour&#39;s enemies add up to a multiple of 18. Handy combinations for one 18-ammo fighter:</p><table tabindex="0"><thead><tr><th>Enemies</th><th>Hit points</th></tr></thead><tbody><tr><td>2 large</td><td>9 + 9</td></tr><tr><td>3 medium</td><td>6 + 6 + 6</td></tr><tr><td>6 small</td><td>3 × 6</td></tr><tr><td>1 large + 1 medium + 1 small</td><td>9 + 6 + 3</td></tr><tr><td>2 medium + 2 small</td><td>6 + 6 + 3 + 3</td></tr><tr><td>A boss part</td><td>18 or 36</td></tr></tbody></table><p>Balance makes a level <em>possible</em> but not <em>easy</em>: the order of taps still decides whether the 5-slot flight zone jams.</p>',4)),t("h2",g,[e[3]||(e[3]=a("4.2 Level checker {#checker} ",-1)),l(s,{type:"tip",text:"Live"}),e[4]||(e[4]=a()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#_4-2-level-checker-checker","aria-label":'Permalink to "4.2 Level checker {#checker} <Badge type="tip" text="Live" />"'},"​",-1))]),e[11]||(e[11]=d("<p><code>npm run validate:levels</code> (it also runs at the start of every <code>npm run build</code>) checks each <code>src/levels/level-*.json</code>:</p><ol><li><strong>Well formed</strong>: known cell letters, every stage has enemies, a boss (2–8 parts) only in the last stage, <code>hpPerEnemy</code> between 20 and 40.</li><li><strong>Compact, full hangar</strong>: no empty cells, rows and columns differ by at most 1, fewer walls than the shorter side.</li><li><strong>Balanced</strong>: ammo equals hit points for every colour.</li><li><strong>Winnable</strong>: a solver searches tap orders, modelling a patient player who lets the flight zone finish shooting before each tap. It uses the game&#39;s own stage layout, so it respects shielding (front targets first), target order and the oldest-first ammo rule. The build fails if no winning order exists. The solver doesn&#39;t model time, so it can&#39;t see flight-zone HP; that is tuned by playtesting (see 4.4).</li><li><strong>Difficulty signal</strong>: the <em>random win rate</em> is the share of 2,000 games of random legal taps that win. Lower means harder. It varies by about ±1 point between runs.</li></ol><p><code>node scripts/validate-levels.ts --solution</code> also prints a winning tap order (row,col) for each level.</p>",3)),t("h2",m,[e[6]||(e[6]=a("4.3 Shipped levels ",-1)),l(s,{type:"tip",text:"Live"}),e[7]||(e[7]=a()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#_4-3-shipped-levels","aria-label":'Permalink to "4.3 Shipped levels <Badge type="tip" text="Live" />"'},"​",-1))]),e[12]||(e[12]=d(`<p>Legend: <code>#</code> wall · letters are fighters (<strong>R</strong>ed <strong>B</strong>lue <strong>G</strong>reen <strong>Y</strong>ellow <strong>P</strong>urple <strong>O</strong>range <strong>C</strong>yan <strong>K</strong> pink). The top row touches the flight zone and is the only row that can launch at the start.</p><table tabindex="0"><thead><tr><th>#</th><th>Name</th><th>Grid (cols × rows)</th><th>Fighters</th><th>Colours</th><th>Stages</th><th>hpPerEnemy</th><th>Zone HP</th><th>Random win rate</th></tr></thead><tbody><tr><td>1</td><td>First Flight</td><td>2 × 2</td><td>4</td><td>2</td><td>2</td><td>40</td><td>480 (12 enemies)</td><td>100%</td></tr><tr><td>2</td><td>Wall Drills</td><td>3 × 3, 1 wall</td><td>8</td><td>3</td><td>3</td><td>35</td><td>770 (22)</td><td>~90%</td></tr><tr><td>3</td><td>Boss Debut</td><td>4 × 3</td><td>12</td><td>4</td><td>3 (boss)</td><td>30</td><td>750 (15 + boss)</td><td>~57%</td></tr><tr><td>4</td><td>Crossfire</td><td>5 × 4</td><td>20</td><td>6</td><td>4 (boss)</td><td>25</td><td>1075 (33 + boss)</td><td>~23%</td></tr><tr><td>5</td><td>Armada</td><td>6 × 6, 4 walls</td><td>32</td><td>8</td><td>5 (boss)</td><td>20</td><td>1640 (47 + boss, +500 bonus)</td><td>under 1%</td></tr></tbody></table><p>The grids were found by a search that shuffles each level&#39;s fighters into the compact grid, keeps only layouts the solver can win, and picks the one whose random win rate is closest to that level&#39;s difficulty target.</p><h3 id="level-1-first-flight" tabindex="-1">Level 1: First Flight <a class="header-anchor" href="#level-1-first-flight" aria-label="Permalink to &quot;Level 1: First Flight&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RB</span></span>
<span class="line"><span>BR</span></span></code></pre></div><p>Teaches tapping: the back row can only launch once the front row has gone. Never more than 4 fighters, so the flight zone can&#39;t jam.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies (back row first)</th></tr></thead><tbody><tr><td>1</td><td>Red: 3 small + 1 large · Blue: 3 medium</td></tr><tr><td>2</td><td>Red: 3 medium · Blue: 2 large</td></tr></tbody></table><h3 id="level-2-wall-drills" tabindex="-1">Level 2: Wall Drills <a class="header-anchor" href="#level-2-wall-drills" aria-label="Permalink to &quot;Level 2: Wall Drills&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GBG</span></span>
<span class="line"><span>RBR</span></span>
<span class="line"><span>BR#</span></span></code></pre></div><p>Stage 1 wants only red, but the top row is green and blue. Digging through it takes slots, and launching too many blues and greens early can fill the zone.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large + 3 medium (36)</td></tr><tr><td>2</td><td>Green: 2 large + 3 medium (36) · Blue: 3 small + 1 large (18)</td></tr><tr><td>3</td><td>Red: large + medium + small (18) · Blue: 3 medium + 2 large (36)</td></tr></tbody></table><h3 id="level-3-boss-debut" tabindex="-1">Level 3: Boss Debut <a class="header-anchor" href="#level-3-boss-debut" aria-label="Permalink to &quot;Level 3: Boss Debut&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GRYY</span></span>
<span class="line"><span>BRGR</span></span>
<span class="line"><span>YBBG</span></span></code></pre></div><p>The first boss, with 4 parts: the nose (red) shields the core (yellow), so the nose has to fall first.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large (18) · Blue: 3 medium (18)</td></tr><tr><td>2</td><td>Green: large + medium + small · Yellow: 3 medium · Red: 2 medium + 2 small (18 each)</td></tr><tr><td>3</td><td><strong>Boss &quot;Iron Hawk&quot;</strong>: wings Blue 36 and Green 36 · core Yellow 36 · nose Red 18</td></tr></tbody></table><h3 id="level-4-crossfire" tabindex="-1">Level 4: Crossfire <a class="header-anchor" href="#level-4-crossfire" aria-label="Permalink to &quot;Level 4: Crossfire&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RROGB</span></span>
<span class="line"><span>OBYPG</span></span>
<span class="line"><span>PGYRY</span></span>
<span class="line"><span>PBBRO</span></span></code></pre></div><p>Six colours in a full 5 × 4 hangar. Stages 2 and 3 stack two or three rows of enemies, so front rows of the wrong colour hold back the colours behind them.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large · Blue: 3 medium · Green: large + medium + small (18 each)</td></tr><tr><td>2</td><td>Yellow: 2 large · Purple: 3 medium · Orange: 6 small · Red: large + medium + small (18 each)</td></tr><tr><td>3</td><td>Blue: 2 large · Green: 3 medium · Yellow: 2 medium + 2 small · Orange: 2 large (18 each)</td></tr><tr><td>4</td><td><strong>Boss &quot;Twin Talon&quot;</strong>: wings Red 36 and Blue 36 · core Green 18 · nose Yellow 18 · engines Purple 36 and Orange 18</td></tr></tbody></table><h3 id="level-5-armada" tabindex="-1">Level 5: Armada <a class="header-anchor" href="#level-5-armada" aria-label="Permalink to &quot;Level 5: Armada&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KCRGBB</span></span>
<span class="line"><span>OY#PPC</span></span>
<span class="line"><span>BOOGP#</span></span>
<span class="line"><span>GC#RRY</span></span>
<span class="line"><span>YRGYK#</span></span>
<span class="line"><span>KCKBPO</span></span></code></pre></div><p>Eight colours, 32 fighters (4 per colour, 72 ammo per colour, 576 in total) and the lowest zone HP per enemy. Random tapping almost never wins.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large · Blue: 3 medium · Green: 2 large · Yellow: large + medium + small (18 each)</td></tr><tr><td>2</td><td>Purple: 2 large · Orange: 3 medium · Cyan: 2 large · Pink: 2 medium + 2 small (18 each)</td></tr><tr><td>3</td><td>Red · Blue · Orange · Cyan: 2 large each · Purple · Green: 3 medium each (18 each)</td></tr><tr><td>4</td><td>Yellow: 2 large · Pink: 2 large · Red: 3 medium · Blue: large + medium + small · Green: 2 large (18 each)</td></tr><tr><td>5</td><td><strong>Boss &quot;Dread Armada&quot;</strong> (all 8 slots): wings Red 18 and Blue 18 · core Green 18 · nose Yellow 36 · engines Purple 36 and Orange 36 · gun pods Cyan 36 and Pink 36</td></tr></tbody></table><h2 id="hp-tuning" tabindex="-1">4.4 Flight-zone HP tuning <a class="header-anchor" href="#hp-tuning" aria-label="Permalink to &quot;4.4 Flight-zone HP tuning {#hp-tuning}&quot;">​</a></h2><p>Measured on level 5 by a script that plays the solver&#39;s tap order. The numbers below were taken at zone HP 1140, before the +500 bonus (10 HP per enemy bullet):</p><table tabindex="0"><thead><tr><th>Player model</th><th>Time</th><th>Enemy bullets landed</th><th>Zone HP left</th></tr></thead><tbody><tr><td>Taps the next fighter the moment a slot is free</td><td>53 s</td><td>59</td><td>~48% (now ~64% of 1640)</td></tr><tr><td>Waits for every volley to finish before each tap</td><td>111 s</td><td>256</td><td>0%: destroyed after ~114 hits (now ~164)</td></tr></tbody></table><p>A real player sits between the two. Level 5 has a <code>zoneHpBonus</code> of 500 on top of the formula to give players more room. To make a level more forgiving, raise its <code>hpPerEnemy</code> or add a <code>zoneHpBonus</code>; to change all levels at once, change <code>enemyBulletDamage</code> in <code>src/game/rules.ts</code>.</p><h2 id="_4-5-making-a-level" tabindex="-1">4.5 Making a level <a class="header-anchor" href="#_4-5-making-a-level" aria-label="Permalink to &quot;4.5 Making a level&quot;">​</a></h2><p>See the developer guide&#39;s <a href="./../guide/level-design">Level design</a> page for the JSON format and workflow.</p>`,29))])}const B=n(h,[["render",c]]);export{k as __pageData,B as default};
